1	import Script from "next/script";
2	import type { PublicTrackingConfig } from "@/lib/tracking";
3	
4	/**
5	 * Browser-side ad tags: Meta Pixel + Google Ads/GA4 gtag. Server component — it's
6	 * handed the PUBLIC config (no CAPI token) read from Settings, and renders nothing
7	 * unless an ID is set. Also installs `window.nxTrack(event, params)` so any client
8	 * component can fire a conversion (e.g. a Purchase on the order-success view) to
9	 * BOTH Meta and Google in one call, using a shared event_id for dedup with CAPI.
10	 */
11	export function ConversionTags({ config }: { config: PublicTrackingConfig }) {
12	  const { metaPixelId, ga4Id, googleAdsId, googleAdsPurchaseLabel } = config;
13	  if (!metaPixelId && !ga4Id && !googleAdsId) return null;
14	
15	  const gtagId = ga4Id || googleAdsId; // one gtag.js load covers both
16	  return (
17	    <>
18	      {metaPixelId && (
19	        <Script id="meta-pixel" strategy="afterInteractive">
20	          {`!function(f,b,e,v,n,t,s){if(f.fbq)return;n=f.fbq=function(){n.callMethod?
21	n.callMethod.apply(n,arguments):n.queue.push(arguments)};if(!f._fbq)f._fbq=n;
22	n.push=n;n.loaded=!0;n.version='2.0';n.queue=[];t=b.createElement(e);t.async=!0;
23	t.src=v;s=b.getElementsByTagName(e)[0];s.parentNode.insertBefore(t,s)}(window,
24	document,'script','https://connect.facebook.net/en_US/fbevents.js');
25	fbq('init','${metaPixelId}');fbq('track','PageView');`}
26	        </Script>
27	      )}
28	      {gtagId && (
29	        <>
30	          <Script src={`https://www.googletagmanager.com/gtag/js?id=${gtagId}`} strategy="afterInteractive" />
31	          <Script id="gtag-init" strategy="afterInteractive">
32	            {`window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}
33	gtag('js',new Date());${ga4Id ? `gtag('config','${ga4Id}');` : ""}${googleAdsId ? `gtag('config','${googleAdsId}');` : ""}`}
34	          </Script>
35	        </>
36	      )}
37	      {/* Unified conversion helper. Usage: window.nxTrack('Purchase',{value:3.29,currency:'USD',eventId}) */}
38	      <Script id="nx-track" strategy="afterInteractive">
39	        {`window.nxTrack=function(evt,p){p=p||{};try{
40	if(window.fbq){fbq('track',evt,{value:p.value,currency:p.currency||'USD'},p.eventId?{eventID:p.eventId}:undefined);}
41	if(window.gtag){
42	  if('${ga4Id}')gtag('event',evt.toLowerCase(),{value:p.value,currency:p.currency||'USD'});
43	  ${googleAdsId && googleAdsPurchaseLabel ? `if(evt==='Purchase')gtag('event','conversion',{send_to:'${googleAdsId}/${googleAdsPurchaseLabel}',value:p.value,currency:p.currency||'USD',transaction_id:p.eventId||''});` : ""}
44	}
45	}catch(e){}};`}
46	      </Script>
47	    </>
48	  );
49	}
