1	// Shared VPS order core — used by the wallet flow (lib/actions.ts orderServer),
2	// the direct-pay flow (payAndDeploy), and the Stripe confirm route so a paid
3	// checkout can provision immediately. Plain server module (not "use server").
4	import { z } from "zod";
5	import type { User } from "@prisma/client";
6	import { db } from "./db";
7	import { debitWallet, InsufficientBalanceError } from "./wallet";
8	import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
9	import { dedicatedIpMonthlyCents } from "./dedicated-ip";
10	import { capacityCheck, diskCapacityCheck } from "./capacity";
11	import { invoiceCreateData } from "./invoices";
12	import { maybeRewardReferral } from "./actions-growth";
13	import { currentPromo, promoPriceCents } from "./promotions";
14	import { extraDiskPerGbCents } from "./disk-expand";
15	import {
16	  EXTRA_DISK_MAX_ADD_GB,
17	  EXTRA_DISK_MAX_TOTAL_GB,
18	  effectiveDiskGB,
19	  extraDiskCentsAt,
20	  extraDiskLabel,
21	  normalizeExtraDiskGB,
22	} from "./extra-disk";
23	import { getSettingBool } from "./settings";
24	import { couponOrderDiscountCents } from "./coupon-order";
25	
26	export class OrderError extends Error {}
27	
28	export const orderSchema = z.object({
29	  planId: z.string().min(1),
30	  osTemplateId: z.string().min(1),
31	  hostname: z
32	    .string()
33	    .min(3)
34	    .max(40)
35	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
36	  // Deploy-time extra-disk upsell. Coerced + step-normalized by
37	  // normalizeExtraDiskGB before it reaches here, so this is a range guard only.
38	  extraDiskGB: z.coerce.number().int().min(0).max(EXTRA_DISK_MAX_ADD_GB).optional(),
39	  // Optional checkout promo code. Uppercased + trimmed; the discount + all
40	  // redemption guards live in orderQuote / placeOrder.
41	  couponCode: z.string().trim().max(32).optional(),
42	});
43	
44	export type OrderIntent = {
45	  planId: string;
46	  osTemplateId: string;
47	  hostname: string;
48	  nodeId?: string;
49	  addonMalware?: boolean;
50	  addonBackup?: boolean;
51	  addonDocker?: boolean;
52	  termMonths?: number;
53	  dedicatedIp?: boolean;
54	  sshPublicKey?: string;
55	  sshKeyName?: string;
56	  free?: boolean;
57	  /**
58	   * Extra root-disk GB bought at deploy time, ON TOP of the plan's diskGB. The VM
59	   * is provisioned at plan.diskGB + extraDiskGB (worker/index.ts provision), so no
60	   * post-deploy expansion job is needed. Permanent — never shrinks.
61	   */
62	  extraDiskGB?: number;
63	  /** Checkout promo code (e.g. a "one free month" coupon), uppercased. */
64	  couponCode?: string;
65	};
66	
67	/**
68	 * The price an order was SOLD at: the total, and the promo rate that produced it.
69	 * Fixed ONCE — before any money moves — and carried to the moment it is charged.
70	 *
71	 * REAL INCIDENT (2026-07-26 customer-journey rehearsal, H2). The card-paid deploy
72	 * path quoted a total, charged the CARD its share of that total at Stripe, and
73	 * then — on the confirm redirect, minutes or hours later — re-ran `orderQuote`
74	 * and debited whatever came back. That re-run includes `currentPromo(new Date())`,
75	 * and lib/promotions.ts always has an active sale that rotates by calendar date,
76	 * so a rotation between "customer clicked Deploy" and "customer came back from
77	 * Stripe" re-priced the order AFTER the card had cleared and took the difference
78	 * out of the wallet with no new consent. With no balance to take it from, the
79	 * payment was captured and no server was created.
80	 *
81	 * `lib/resize.ts` and `lib/disk-expand.ts` already carried the amount through
82	 * Stripe metadata for exactly this reason; the order path was the one that
83	 * re-derived it. Same rule as lib/renewal-quote.ts and lib/proration.ts: a figure
84	 * the customer was shown is not recomputed later, it is carried.
85	 *
86	 * `promoPercent` and `promoName` travel WITH the total because they are not
87	 * decoration. `Server.termPromoPercent` records the rate a term was actually sold
88	 * at (every later proration prices against it), and the promo name is the ledger
89	 * and invoice text the customer reads. Honouring a 30%-off price while stamping
90	 * today's 15% would hand every later proration the wrong basis and print a
91	 * discount on the invoice that does not match the money taken.
92	 */
93	export type OrderPrice = {
94	  /** Total to charge, in cents — the figure the customer consented to. */
95	  chargeCents: number;
96	  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
97	  promoPercent: number;
98	  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
99	  promoName: string;
100	};
101	
102	/** The sold price implied by a quote — the ONE place a quote becomes a price. */
103	export function orderPriceOf(quote: {
104	  chargeCents: number;
105	  promo: { discountPercent: number; name: string };
106	}): OrderPrice {
107	  return {
108	    chargeCents: quote.chargeCents,
109	    promoPercent: quote.promo.discountPercent,
110	    promoName: quote.promo.name,
111	  };
112	}
113	
114	/**
115	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
116	 * well-formed: a half-parsed price would be worse than no price at all, because
117	 * the caller's fallback (re-quote) is at least internally consistent.
118	 */
119	export function parseOrderPrice(raw: unknown): OrderPrice | null {
120	  let obj: unknown = raw;
121	  if (typeof raw === "string") {
122	    try {
123	      obj = JSON.parse(raw);
124	    } catch {
125	      return null;
126	    }
127	  }
128	  if (!obj || typeof obj !== "object") return null;
129	  const { chargeCents, promoPercent, promoName } = obj as Record<string, unknown>;
130	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
131	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
132	  if (promoPercent < 0 || promoPercent > 100) return null;
133	  return { chargeCents, promoPercent, promoName: typeof promoName === "string" ? promoName : "" };
134	}
135	
136	/** Extract a plain OrderIntent from a deploy form. */
137	export function intentFromFormData(formData: FormData): OrderIntent {
138	  return {
139	    planId: String(formData.get("planId") ?? ""),
140	    osTemplateId: String(formData.get("osTemplateId") ?? ""),
141	    hostname: String(formData.get("hostname") ?? ""),
142	    nodeId: String(formData.get("nodeId") ?? "") || undefined,
143	    addonMalware: formData.get("addon_malware") === "1",
144	    addonBackup: formData.get("addon_backup") === "1",
145	    addonDocker: formData.get("addon_docker") === "1",
146	    termMonths: Number(formData.get("termMonths") ?? 1),
147	    dedicatedIp: formData.get("dedicatedIp") === "1",
148	    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
149	    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
150	    free: formData.get("free") === "1",
151	    // Rounded DOWN to a purchasable step — a malformed value can only ever cost
152	    // the customer less, never more. Left UNDEFINED (not 0) when nothing was
153	    // bought so it drops out of JSON.stringify: the intent is round-tripped
154	    // through Stripe metadata, which is capped at 500 chars (lib/stripe.ts
155	    // createOrderCheckout), and every byte of headroom matters there.
156	    extraDiskGB: normalizeExtraDiskGB(formData.get("extraDiskGB")) || undefined,
157	    couponCode: String(formData.get("couponCode") ?? "").trim().toUpperCase() || undefined,
158	  };
159	}
160	
161	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
162	async function scheduleNode(planRamMB: number) {
163	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
164	  if (nodes.length === 0) return null;
165	  const loads = await Promise.all(
166	    nodes.map(async (n) => {
167	      const agg = await db.server.findMany({
168	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
169	        select: { plan: { select: { ramMB: true } } },
170	      });
171	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
172	      return { node: n, free: n.capacityRamMB - used };
173	    }),
174	  );
175	  loads.sort((a, b) => b.free - a.free);
176	  return loads[0].node;
177	}
178	
179	/** Validate + price an order without placing it. Throws OrderError on any problem. */
180	export async function orderQuote(intent: OrderIntent) {
181	  const parsed = orderSchema.safeParse(intent);
182	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
183	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
184	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
185	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
186	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
187	    throw new OrderError(
188	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
189	    );
190	  }
191	  const term = vpsTerm(Number(intent.termMonths ?? 1));
192	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
193	
194	  // Extra root disk, priced per GB/month and multiplied over the term exactly
195	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
196	  // promo — the customer pays the same $/GB whichever term they pick, and renews
197	  // at the same rate). Growth is one-way: this is permanent for the server.
198	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
199	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
200	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
201	  const extraDiskCents = extraDiskMonthlyCents * term.months;
202	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
203	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
204	  }
205	
206	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
207	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
208	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
209	  // real renewal price and this discounted value is the real first-term price.
210	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
211	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
212	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
213	  const promo = currentPromo(new Date());
214	  const planFirstTermCents = promoPriceCents(regularPlanCents, promo);
215	
216	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
217	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
218	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
219	  // so the deploy preview can show it; the redemption itself (count + per-user +
220	  // per-IP guards) is claimed atomically in placeOrder.
221	  let couponId: string | null = null;
222	  let couponDiscountCents = 0;
223	  let couponLabel = "";
224	  let couponError = "";
225	  let couponMaxRedemptions: number | null = null;
226	  let couponFirstTimeOnly = false;
227	  const code = (intent.couponCode ?? "").trim().toUpperCase();
228	  if (code) {
229	    if (!(await getSettingBool("coupons_enabled", true))) {
230	      couponError = "Promo codes are currently disabled.";
231	    } else {
232	      const coupon = await db.coupon.findUnique({ where: { code } });
233	      if (!coupon) {
234	        couponError = "That code isn’t valid.";
235	      } else {
236	        const verdict = couponOrderDiscountCents(
237	          {
238	            kind: coupon.kind,
239	            value: coupon.value,
240	            serviceKind: coupon.serviceKind,
241	            planSlug: coupon.planSlug,
242	            maxTermMonths: coupon.maxTermMonths,
243	            active: coupon.active,
244	            expiresAt: coupon.expiresAt,
245	            maxRedemptions: coupon.maxRedemptions,
246	            timesRedeemed: coupon.timesRedeemed,
247	            minAmountCents: coupon.minAmountCents,
248	          },
249	          {
250	            serviceKind: "VPS",
251	            planSlug: plan.slug,
252	            planMonthlyCents: plan.priceCents,
253	            termMonths: term.months,
254	            planChargeCents: planFirstTermCents,
255	          },
256	          new Date(),
257	        );
258	        if (verdict.ok) {
259	          couponId = coupon.id;
260	          couponDiscountCents = verdict.discountCents;
261	          couponLabel = verdict.label;
262	          couponMaxRedemptions = coupon.maxRedemptions;
263	          couponFirstTimeOnly = coupon.firstTimeOnly;
264	        } else {
265	          couponError = verdict.error;
266	        }
267	      }
268	    }
269	  }
270	
271	  const chargeCents = planFirstTermCents - couponDiscountCents + ipCents + extraDiskCents;
272	  return {
273	    plan,
274	    os,
275	    term,
276	    chargeCents,
277	    promo,
278	    regularPlanCents,
279	    extraDiskGB,
280	    extraDiskMonthlyCents,
281	    extraDiskCents,
282	    couponId,
283	    couponDiscountCents,
284	    couponLabel,
285	    couponError,
286	    couponMaxRedemptions,
287	    couponFirstTimeOnly,
288	  };
289	}
290	
291	/**
292	 * Place an order: validate, charge the wallet (unless a free admin grant),
293	 * create the Server + PROVISION job. Returns the new server id. Does NOT
294	 * redirect. Callers must ensure funds exist (or pass free) — this still
295	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
296	 *
297	 * `sold` overrides the recomputed price with the one the order was actually SOLD
298	 * at — the card-paid path passes the figure stamped on the Checkout session
299	 * BEFORE the card was charged, so the confirm redirect settles the price the
300	 * customer consented to instead of re-pricing against whatever promo is running
301	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
302	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
303	 * quote, which it computed moments ago in the same request. See OrderPrice.
304	 */
305	/**
306	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
307	 * any failure so nothing partial survives. Kept separate from the order tx so a
308	 * wallet order can surface the failure before any money moves, and a card order
309	 * (already paid) can swallow it without stranding the paid provision.
310	 *
311	 * Guards, all enforced here: first-time-only (no prior paid server), the
312	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
313	 * (the two @@unique constraints on CouponRedemption).
314	 */
315	async function claimOrderCoupon(opts: {
316	  couponId: string;
317	  maxRedemptions: number | null;
318	  firstTimeOnly: boolean;
319	  userId: string;
320	  ipHash: string | null;
321	  amountCents: number;
322	}): Promise<void> {
323	  await db.$transaction(async (tx) => {
324	    if (opts.firstTimeOnly) {
325	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
326	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
327	    }
328	    // Atomic conditional increment — the only thing between the last free slot and
329	    // an over-redemption when two orders race for it.
330	    const claim = await tx.coupon.updateMany({
331	      where:
332	        opts.maxRedemptions === null
333	          ? { id: opts.couponId, active: true }
334	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
335	      data: { timesRedeemed: { increment: 1 } },
336	    });
337	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
338	    try {
339	      await tx.couponRedemption.create({
340	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
341	      });
342	    } catch {
343	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
344	      // this person. Throwing rolls back the increment above with it.
345	      throw new OrderError("You’ve already used this code.");
346	    }
347	  });
348	}
