350	/**
351	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
352	 *
353	 * The card leg discounts `cardCents` up front and only settles the redemption
354	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
355	 * paid provision is never stranded. Without this pre-check, a customer who has
356	 * already used a one-per-person code (or isn't first-time) still gets the
357	 * discounted card charge and the swallow hides it. So before we send them to
358	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
359	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
360	 * (a race could still lose the atomic claim at settle time — that path stays
361	 * swallowed by design), but it closes the everyday bypass.
362	 */
363	export async function orderCouponClaimable(opts: {
364	  couponId: string;
365	  firstTimeOnly: boolean;
366	  maxRedemptions: number | null;
367	  userId: string;
368	  ipHash: string | null;
369	}): Promise<{ ok: true } | { ok: false; error: string }> {
370	  if (opts.firstTimeOnly) {
371	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
372	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
373	  }
374	  const byUser = await db.couponRedemption.findUnique({
375	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
376	  });
377	  if (byUser) return { ok: false, error: "You’ve already used this code." };
378	  if (opts.ipHash) {
379	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
380	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
381	  }
382	  if (opts.maxRedemptions !== null) {
383	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
384	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
385	  }
386	  return { ok: true };
387	}
