389	export async function placeOrder(
390	  user: User,
391	  intent: OrderIntent,
392	  sold?: OrderPrice | null,
393	  opts?: { ipHash?: string | null },
394	): Promise<string> {
395	  const quote = await orderQuote(intent);
396	  const { plan, os, term, promo, extraDiskGB, extraDiskMonthlyCents, extraDiskCents } = quote;
397	  // Everything below bills off THESE three, never off `quote.chargeCents` /
398	  // `promo` directly: when a sold price is present it is the whole truth about
399	  // what this order costs and what rate it was sold at.
400	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
401	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
402	  const promoName = sold?.promoName || promo.name;
403	  // Note the intro discount on the billing document (first term only; renews full).
404	  const promoNote = promoPercent > 0 ? ` · ${promoName} ${promoPercent}% off first term` : "";
405	
406	  const cap = await capacityCheck(plan.id);
407	  if (!cap.ok) throw new OrderError(cap.reason);
408	
409	  let nodeId: string | null = null;
410	  if (intent.nodeId) {
411	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
412	    if (!n) throw new OrderError("Selected location is not available.");
413	    nodeId = n.id;
414	  } else {
415	    const n = await scheduleNode(plan.ramMB);
416	    nodeId = n?.id ?? null;
417	  }
418	
419	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
420	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
421	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
422	
423	  const addons = {
424	    malwareScanner: !!intent.addonMalware,
425	    dailyBackup: !!intent.addonBackup,
426	    docker: !!intent.addonDocker,
427	  };
428	  const isAdmin = user.role === "ADMIN";
429	  const freeRequested = !!intent.free && isAdmin;
430	  if (!freeRequested && user.balanceCents < chargeCents) throw new OrderError("Insufficient balance.");
431	
432	  // Claim the coupon BEFORE the order tx, so a wallet order fails cleanly (no
433	  // money moved) if the last slot just went. A free admin grant never consumes a
434	  // customer coupon. On the card-settle path the payment already cleared, so a
435	  // late claim failure must not strand the paid provision — log and continue.
436	  if (!freeRequested && quote.couponId && quote.couponDiscountCents > 0) {
437	    try {
438	      await claimOrderCoupon({
439	        couponId: quote.couponId,
440	        maxRedemptions: quote.couponMaxRedemptions,
441	        firstTimeOnly: quote.couponFirstTimeOnly,
442	        userId: user.id,
443	        ipHash: opts?.ipHash ?? null,
444	        amountCents: quote.couponDiscountCents,
445	      });
446	    } catch (e) {
447	      if (!sold) throw e; // wallet path: nothing charged yet — surface it
448	      console.error(`[order] coupon claim failed on a paid order for ${user.id}`, e);
449	    }
450	  }
451	
452	  const newKey = (intent.sshPublicKey ?? "").trim();
453	  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);
454	
455	  let server;
456	  try {
457	    server = await db.$transaction(async (tx) => {
458	      if (!freeRequested) {
459	        await debitWallet(tx, user.id, chargeCents);
460	        await tx.walletTransaction.create({
461	          data: {
462	            userId: user.id,
463	            amountCents: -chargeCents,
464	            description: `Order: ${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`,
465	          },
466	        });
467	        // Billing document for the charge — created inside the same debit tx so it
468	        // shares the transaction's atomicity (a rolled-back charge leaves no invoice).
469	        // Extra disk gets its OWN line so the customer can see exactly what the
470	        // permanent storage costs; the lines always sum back to chargeCents.
471	        const lineDesc = `${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`;
472	        const planLineCents = chargeCents - extraDiskCents;
473	        await tx.invoice.create({
474	          data: invoiceCreateData({
475	            userId: user.id,
476	            description: lineDesc,
477	            status: "PAID",
478	            period: { start: new Date(), end: addMonths(new Date(), term.months) },
479	            lineItems: [
480	              { description: lineDesc, qty: 1, unitCents: planLineCents, amountCents: planLineCents },
481	              ...(extraDiskCents > 0
482	                ? [
483	                    {
484	                      description:
485	                        `${extraDiskLabel(extraDiskGB)} — ${term.label} ` +
486	                        `($${(extraDiskMonthlyCents / 100).toFixed(2)}/mo, permanent: storage can be added but never removed)`,
487	                      qty: 1,
488	                      unitCents: extraDiskCents,
489	                      amountCents: extraDiskCents,
490	                    },
491	                  ]
492	                : []),
493	            ],
494	          }),
495	        });
496	      }
497	      if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
498	        const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
499	        if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
500	      }
501	      const s = await tx.server.create({
502	        data: {
503	          name: intent.hostname,
504	          hostname: intent.hostname,
505	          userId: user.id,
506	          planId: plan.id,
507	          osTemplateId: os.id,
508	          nodeId,
509	          addons,
510	          // The wizard sells "Daily auto-backups" ("Nightly snapshots to separate
511	          // storage for easy restore") and re-confirms it on the Review step, but
512	          // `addons.dailyBackup` was write-only: the worker declares the key and
513	          // never reads it, and the REAL scheduler (worker/backup-schedule.ts)
514	          // keys off `autoBackup` + `backupIntervalHours`, whose only writer was
515	          // the Backups tab. Nothing bridged the two, so EVERY server in the live
516	          // DB carried `addons.dailyBackup` with `autoBackup: false` and no backup
517	          // job was ever enqueued. A customer would discover the safety net they
518	          // were promised did not exist at the moment they needed it. Bridge it
519	          // here, at the point of sale.
520	          autoBackup: !!intent.addonBackup,
521	          backupIntervalHours: intent.addonBackup ? 24 : null,
522	          termMonths: term.months,
523	          // THE RATE THIS TERM WAS SOLD AT, recorded at the moment of sale. Every
524	          // later proration prices the plan delta against this number instead of
525	          // whatever promo happens to be running when the customer clicks resize
526	          // (lib/proration.ts) — otherwise the customer chooses the rate for each
527	          // half of a round trip by choosing the date, and pockets the spread.
528	          // `chargeCents` above is literally promoPriceCents(regular, promo), so
529	          // this scalar and the cash collected describe the same transaction.
530	          // A free admin grant recorded as 100: nothing was paid for these months,
531	          // so nothing may ever prorate out of them.
532	          //
533	          // `promoPercent` — not `promo.discountPercent` — because a card-paid
534	          // order settles the rate it was SOLD at (see OrderPrice), which may no
535	          // longer be the promo running now. Recording today's rate against a
536	          // price collected under a different one is exactly the drift this
537	          // column exists to prevent.
538	          termPromoPercent: freeRequested ? 100 : promoPercent,
539	          // Persisted BEFORE the PROVISION job runs, so the worker clones the VM
540	          // and resizes scsi0 straight to plan.diskGB + extraDiskGB — the server is
541	          // born at its full size, with no separate expansion job.
542	          extraDiskGB,
543	          wantsDedicatedIp: !!intent.dedicatedIp,
544	          isFree: freeRequested,
545	          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
546	        },
547	      });
548	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
549	      return s;
550	    });
551	  } catch (e) {
552	    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
553	    throw e;
554	  }
555	
556	  await db.auditLog.create({
557	    data: {
558	      userId: user.id,
559	      action: "server.order",
560	      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo extraDisk=${extraDiskGB}GB free=${freeRequested}`,
561	    },
562	  });
563	  if (!freeRequested) {
564	    try {
565	      await maybeRewardReferral(user.id);
566	    } catch {
567	      /* non-fatal */
568	    }
569	  }
570	  return server.id;
571	}
