69	/**
70	 * Grant the configured signup free credit to a freshly-registered user, once.
71	 * No-op when the amount is 0 or the account already has signup credit.
72	 *
73	 * PRIVATE ON PURPOSE. This used to be an export of lib/actions-growth.ts — a
74	 * `"use server"` file — which made "credit an arbitrary `userId`" a public
75	 * network endpoint whose only defence was a guard that inspected request
76	 * headers. It has exactly one caller, `register` below, and a function with one
77	 * in-process caller has no business being an endpoint at all. Keeping it here,
78	 * unexported, is the same reasoning that moved `safeNext` and
79	 * `verifyTotpForUser` out of `"use server"` files.
80	 *
81	 * It also removes a live fragility: the old guard resolved the acting account
82	 * from the session, and `register` calls this immediately after minting that
83	 * session, so the grant's success depended on request-scoped session state
84	 * settling mid-action. Nothing about "did this new account already get its
85	 * welcome credit?" needs the session — `signupCreditCents` on the row is the
86	 * only fact that matters, and it is what makes the grant idempotent.
87	 */
88	async function grantSignupCredit(userId: string): Promise<number> {
89	  // Prefer the admin-editable setting (`signup_free_credit_cents`); fall back to
90	  // the legacy SIGNUP_FREE_CREDIT_CENTS env default when the setting is unset.
91	  const cents = await getSettingInt("signup_free_credit_cents", signupFreeCreditCents());
92	  if (cents <= 0) return 0;
93	  // Idempotent claim: only ever grants against a row that has no signup credit
94	  // yet, so a retry (or two concurrent registrations of the same account, which
95	  // the unique email index already prevents) cannot pay twice.
96	  const claimed = await db.user.updateMany({
97	    where: { id: userId, signupCreditCents: 0 },
98	    data: { balanceCents: { increment: cents }, signupCreditCents: cents },
99	  });
100	  if (claimed.count === 0) return 0;
101	  await db.walletTransaction.create({
102	    data: { userId, amountCents: cents, description: "Welcome credit" },
103	  });
104	  return cents;
105	}
