145	export async function register(prev: any, formData: FormData): Promise<{ error?: string }> {
146	  const parsed = credsSchema
147	    .extend({
148	      name: z.string().min(1, "Enter your name").max(100, "Name is too long"),
149	      password: z
150	        .string()
151	        .min(8, "Password must be at least 8 characters")
152	        .max(200, "Password is too long")
153	        .regex(/[a-zA-Z]/, "Password must include a letter")
154	        .regex(/[0-9]/, "Password must include a number"),
155	    })
156	    .safeParse({
157	    // Canonicalise BEFORE validating, so `  Alice@Example.com ` is stored in the
158	    // one form every lookup will use. See lib/email-normalize.ts.
159	    email: normalizeEmail(formData.get("email")),
160	    password: formData.get("password"),
161	    name: formData.get("name"),
162	  });
163	  // Say what is actually wrong. This used to collapse four precise, already
164	  // written messages into "Enter a valid email, name, and password (min 8
165	  // chars)." — so a customer whose only problem was a missing digit was told
166	  // about a length rule their 8-character password already satisfied, and had
167	  // no way to work out what the form wanted. The deploy path (`payAndDeploy`
168	  // below, via lib/order.ts) has surfaced the real issue since it was written;
169	  // this is the same one line.
170	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Check the form and try again." };
171	  const { email, password, name } = parsed.data;
172	
173	  // Throttle signups per email+IP (reuses the login rate-limit helper) to curb
174	  // automated account creation and welcome-credit farming.
175	  const regIp = clientIp(await headers());
176	  const regRl = checkRateLimit(`register:${email}:${regIp}`, { max: 5, windowMs: 15 * 60 * 1000 });
177	  if (!regRl.ok) return { error: `Too many attempts. Try again in ${regRl.retryAfterSec}s.` };
178	
179	  const existing = await db.user.findUnique({ where: { email } });
180	  if (existing) return { error: "An account with that email already exists." };
181	
182	  // Capture a referral from the `ref` cookie (set by the register page) if the
183	  // code maps to a real user. Self-referral is impossible here (new account).
184	  const jar = await cookies();
185	  const refCode = jar.get(REF_COOKIE)?.value?.trim().toUpperCase();
186	  let referredById: string | null = null;
187	  if (refCode) {
188	    const referrer = await db.user.findUnique({ where: { referralCode: refCode } });
189	    if (referrer) referredById = referrer.id;
190	  }
191	
192	  const referralCode = await uniqueReferralCode();
193	  const user = await db.user.create({
194	    data: {
195	      email,
196	      name,
197	      passwordHash: await bcrypt.hash(password, 12),
198	      referralCode,
199	      referredById,
200	    },
201	  });
202	  await audit(user.id, "user.register", referredById ? `ref=${refCode}` : undefined);
203	  await createSession(user.id);
204	  // Grant signup free credit (no-op unless the configured amount is > 0).
205	  //
206	  // Still non-fatal — a failure here must not cost the customer the account they
207	  // just created — but no longer SILENT. `signup_free_credit_cents` is an
208	  // admin-editable field that the settings panel reports "Saved." for, and an
209	  // empty `catch {}` here is exactly how this codebase has repeatedly ended up
210	  // with a control that reports success and does nothing. If the grant fails,
211	  // that fact is now in the logs and there is a wallet row to reconcile against.
212	  try {
213	    await grantSignupCredit(user.id);
214	  } catch (e) {
215	    console.error("[register] signup credit grant failed for", user.id, e);
216	  }
217	  jar.delete(REF_COOKIE);
218	  try {
219	    const { sendMail, emails } = await import("./mailer");
220	    const tpl = emails.welcome(name);
221	    await sendMail({ to: email, subject: tpl.subject, html: tpl.html, userId: user.id, kind: "welcome" });
222	  } catch { /* email is best-effort */ }
223	  // Send the verification link. Best-effort like the welcome mail and it does
224	  // NOT block the redirect: signing up and looking around stay open, only
225	  // buying and provisioning wait on the click (lib/email-verification.ts). If
226	  // this send fails the account is still usable and still resendable from the
227	  // portal banner — the customer is never stranded on a screen we control.
228	  try {
229	    const { sendVerificationEmail } = await import("./email-verification");
230	    await sendVerificationEmail(user);
231	  } catch (e) {
232	    console.error("[register] verification email failed:", e);
233	  }
234	  redirect("/dashboard");
235	}
