254	  // `x-forwarded-for.split(",")[0]`. nginx forwards the header with
255	  // `$proxy_add_x_forwarded_for`, which APPENDS the peer it saw to whatever the
256	  // client sent — so the leftmost entry is a free-text field the caller filled
257	  // in, and keying on it meant an attacker could rotate one header value per
258	  // request and never bind this limiter at all. That is the limiter standing
259	  // between a known email address and unlimited password guesses, and (below)
260	  // unlimited 2FA code guesses once a password is known. See the docblock on
261	  // `clientIp` for the measurement.
262	  const rlId = `${parsed.data.email}:${clientIp(await headers())}`;
263	  const maxAttempts = Math.max(1, await getSettingInt("login_ratelimit_max", 10));
264	  const rl = checkRateLimit(`login:${rlId}`, { max: maxAttempts, windowMs: 15 * 60 * 1000 });
265	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
266	
267	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
268	  // ALWAYS spend one bcrypt comparison, even when the address does not exist.
269	  //
270	  // `!user || !(await bcrypt.compare(...))` short-circuits: with no account, bcrypt
271	  // never ran. The reply text was correctly identical either way, but the reply
272	  // TIME was not — bcrypt at cost 12 is ~250ms against a single indexed SELECT, a
273	  // gap one sample per address is enough to read. That turns the login form into
274	  // an account-enumeration oracle: "does this person bank here", answered for any
275	  // address, at scale, without ever guessing a password.
276	  //
277	  // It was materially worse while the throttle above was keyed on the
278	  // caller-supplied first hop of `x-forwarded-for`, because the rate limit that
279	  // would otherwise cap sampling could itself be stepped around per request. That
280	  // is fixed, but a defence that only works because another defence works is not
281	  // one, so the timing is equalised on its own terms.
282	  //
283	  // The comparison against DUMMY_HASH is discarded — it exists solely to spend the
284	  // same ~250ms. Keep the reply string identical to the wrong-password case.
285	  const passwordOk = user
286	    ? await bcrypt.compare(parsed.data.password, user.passwordHash)
287	    : ((await bcrypt.compare(parsed.data.password, DUMMY_PASSWORD_HASH)), false);
288	  // `!user` is repeated here purely so TypeScript narrows `user` for the code
289	  // below. It is NOT a short-circuit any more: `passwordOk` above has already
290	  // spent the bcrypt comparison in both branches, which is the whole point.
291	  if (!user || !passwordOk) {
292	    return { error: "Invalid email or password." };
293	  }
294	  if (user.suspended) return { error: "This account is suspended." };
295	
296	  // Two-factor challenge, if enabled on the account.
297	  if (user.totpEnabled) {
298	    const code = String(formData.get("code") ?? "").trim();
299	    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
300	    if (!(await verifyTotpForUser(user.id, code))) {
301	      return { error: "Invalid 2FA code.", needs2fa: true };
302	    }
303	  }
304	
305	  resetRateLimit(`login:${rlId}`);
306	  await audit(user.id, "user.login");
307	  await createSession(user.id);
308	  // Land where they were HEADING, not on a generic dashboard.
309	  //
310	  // Public CTAs like "Migrate free →" send a logged-out visitor into
311	  // /dashboard/..., which bounces to /login and — until now — discarded what they
312	  // clicked. They signed in and arrived somewhere unrelated, with no route back to
313	  // the thing they wanted. Seven CTAs did this, the worst being "Contact support"
314	  // on the PUBLIC help page, where a prospect met a login wall instead of /contact.
315	  //
316	  // `safeNext` only ever returns a path on THIS site (see its definition): an
317	  // open redirect on a login form is a phishing primitive, so an absolute URL, a
318	  // protocol-relative `//evil.test` or anything that is not a single-slash path is
319	  // discarded rather than sanitised.
320	  const next = safeNext(formData.get("next"));
321	  redirect(next ?? (user.role === "ADMIN" ? "/admin" : "/dashboard"));
322	}
