331	/**
332	 * Enforce the admin-configured per-user server cap (`max_servers_per_user`,
333	 * default 10; 0 = unlimited). Counts every server the user owns that isn't being
334	 * torn down (DELETING). Returns an error message when the cap is reached, else null.
335	 */
336	async function serverLimitError(userId: string): Promise<string | null> {
337	  const cap = await getSettingInt("max_servers_per_user", 10);
338	  if (cap <= 0) return null; // 0 (or negative) = unlimited
339	  const owned = await db.server.count({ where: { userId, status: { notIn: ["DELETING"] } } });
340	  if (owned >= cap) {
341	    return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}. Delete one or contact support to raise the cap.`;
342	  }
343	  return null;
344	}
