422	export async function payAndDeploy(
423	  prev: any,
424	  formData: FormData,
425	): Promise<{ error?: string; checkoutUrl?: string }> {
426	  const user = await requireUser();
427	  // Spend path: never move a customer's money while an admin is impersonating them.
428	  await assertNotImpersonating();
429	  // Same verification gate every purchase path applies. This is the CARD path, so it is the
430	  // one where an unreachable address is most expensive: without it we would take
431	  // a real payment for a machine whose credentials have nowhere to go.
432	  const unverified = await emailVerificationError(user);
433	  if (unverified) return { error: unverified };
434	  // Per-user server cap — the same one `orderGameServer` enforces for game tiers.
435	  const limitErr = await serverLimitError(user.id);
436	  if (limitErr) return { error: limitErr };
437	  const intent = intentFromFormData(formData);
438	
439	  let quote;
440	  try {
441	    quote = await orderQuote(intent);
442	  } catch (e) {
443	    if (e instanceof OrderError) return { error: e.message };
444	    throw e;
445	  }
446	
447	  const isAdmin = user.role === "ADMIN";
448	  const freePath = !!intent.free && isAdmin;
449	
450	  // Wallet-aware split. The customer's Review screen computes the exact same split
451	  // (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
452	  // `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
453	  // the balance. Free admin grants skip the split entirely (no money moves).
454	  const useWallet = formData.get("useWallet") !== "0";
455	  const { walletApplied, cardCents } = freePath
456	    ? { walletApplied: 0, cardCents: 0 }
457	    : walletSplit({ dueCents: quote.chargeCents, balanceCents: user.balanceCents, useWallet });
458	
459	  // Card portion is $0 (free admin grant, or the wallet fully covers the charge) →
460	  // provision straight away. placeOrder debits the FULL chargeCents from the wallet
461	  // (or nothing, for a free grant); the balance check inside it holds because a
462	  // $0 card portion means balance >= chargeCents.
463	  if (freePath || cardCents <= 0) {
464	    let serverId: string;
465	    try {
466	      // Hash the claimant IP here (request scope) so placeOrder can enforce a
467	      // coupon's once-per-person guard beyond one-per-account.
468	      const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon");
469	      serverId = await placeOrder(user, intent, null, { ipHash });
470	    } catch (e) {
471	      if (e instanceof OrderError) return { error: e.message };
472	      throw e;
473	    }
474	    redirect(`/dashboard/servers/${serverId}`);
475	  }
476	
477	  // Coupon guard for the CARD path. The wallet path is already safe — its
478	  // placeOrder claim throws and we surface it above (nothing charged). But the
479	  // card leg below discounts `cardCents` up front and settles the redemption only
480	  // AFTER the card clears, where a failed claim is swallowed so a paid provision
481	  // isn't stranded. So a customer who already used a one-per-person code would
482	  // still get the discounted charge. Re-run the per-person guards as reads here
483	  // and refuse before checkout — same messages the wallet path would show.
484	  if (quote.couponId) {
485	    const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon");
486	    const claimable = await orderCouponClaimable({
487	      couponId: quote.couponId,
488	      firstTimeOnly: quote.couponFirstTimeOnly,
489	      maxRedemptions: quote.couponMaxRedemptions,
490	      userId: user.id,
491	      ipHash,
492	    });
493	    if (!claimable.ok) return { error: `${claimable.error} Remove the code to continue at the regular price.` };
494	  }
495	
496	  // Card portion > 0 → charge ONLY the remainder on the card (not the full total).
497	  // On payment success the confirm route credits this card amount to the wallet and
498	  // then placeOrder debits the full chargeCents, so the wallet naturally absorbs
499	  // `walletApplied` and the card the rest — the wallet is never touched before the
500	  // card clears. (walletApplied is implied by cardCents vs. the recomputed charge,
501	  // so it needs no separate metadata field.)
502	  // The price is handed over EXPLICITLY, from the very quote the wallet split above
503	  // was computed from. Without this argument `createOrderCheckout` re-quotes
504	  // internally, microseconds later, from its own `new Date()` — the same function,
505	  // so no formula can drift, but two different instants. A promo boundary (or an
506	  // operator changing a plan price) falling between them would mean the card leg
507	  // and the stamped total were priced against two different worlds, and the wallet
508	  // would silently absorb the difference. One quote, one price, one charge.
509	  const url = await createOrderCheckout(user, cardCents, intent, orderPriceOf(quote));
510	  if (!url) return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
511	  return { checkoutUrl: url };
512	}
