516	async function ownedServer(serverId: string) {
517	  const user = await requireUser();
518	  const server = await db.server.findUnique({ where: { id: serverId } });
519	  if (!server) throw new Error("Not found");
520	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
521	  return { user, server };
