524	export async function serverAction(serverId: string, action: string): Promise<{ error?: string } | void> {
525	  // Returns `{ error }` for anything the CUSTOMER can act on, so ServerControls
526	  // can render it — a `throw` here reaches the browser as Next's redacted generic
527	  // error, discarding the specific, actionable message (e.g. "Delete your data
528	  // volume(s) before reinstalling"). Only genuinely-impossible states still throw.
529	  const { user, server } = await ownedServer(serverId);
530	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
531	    start: "START",
532	    stop: "STOP",
533	    reboot: "REBOOT",
534	    reinstall: "REINSTALL",
535	    delete: "DELETE",
536	  };
537	  const type = allowed[action];
538	  if (!type) throw new Error("Invalid action"); // not reachable from the UI — a real bug if it happens
539	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
540	    return { error: "This server is suspended. Settle the outstanding balance to control it again." };
541	  }
542	
543	  // A reinstall wipes the whole VM, including any block-storage volume the VM
544	  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
545	  //
546	  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
547	  // deliberately keeps `serverId` set so the volume can be re-attached
548	  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
549	  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
550	  // Filtering on ATTACHED therefore missed the worst case: customer fills a
551	  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
552	  // Reinstall — both guards see zero attached volumes, and the purge takes the
553	  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
554	  // by serverId; this path did not. That asymmetry was the bug.
555	  if (type === "REINSTALL") {
556	    const pinnedVolumes = await db.volume.count({ where: { serverId } });
557	    if (pinnedVolumes > 0) {
558	      return {
559	        error:
560	          "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
561	      };
562	    }
563	  }
564	
565	  const pending = await db.job.count({
566	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
567	  });
568	  // Was a silent `return`: the customer clicked Start and nothing happened, ever,
569	  // with no explanation. Tell them why.
570	  if (pending > 0) return { error: "Another operation is already running on this server. Wait for it to finish." };
571	
572	  if (type === "DELETE") {
573	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
574	  }
575	  await db.job.create({ data: { type, serverId } });
576	  await audit(user.id, `server.${action}`, serverId);
577	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
578	  revalidatePath(`/dashboard/servers/${serverId}`);
579	}
