583	export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
584	  const user = await requireUser();
585	  // Spend/credit path: block while impersonating so an admin can't mint or move
586	  // a customer's balance on their behalf.
587	  await assertNotImpersonating();
588	  // Security: never mint free wallet balance in production. The demo gateway that
589	  // credits without a real payment is only ever acceptable in non-production, and
590	  // is refused outright when NODE_ENV === "production" regardless of Stripe.
591	  if (process.env.NODE_ENV === "production") {
592	    return { error: "Please add funds with a card via the secure checkout." };
593	  }
594	  // Once Stripe is configured, the demo gateway is hard-disabled — top-ups must
595	  // go through Checkout.
596	  const { stripeConfigured } = await import("./stripe");
597	  if (stripeConfigured()) {
598	    return { error: "Please add funds with a card via the secure checkout." };
599	  }
600	  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
601	  const topupIp = clientIp(await headers());
602	  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
603	  if (!topupRl.ok) {
604	    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
605	  }
606	  const amount = Number(formData.get("amount"));
607	  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
608	    return { error: "Amount must be between $1 and $1000." };
609	  }
610	  const cents = Math.round(amount * 100);
611	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
612	  const minTopup = await getSettingInt("min_topup_cents", 500);
613	  if (cents < minTopup) {
614	    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
615	  }
616	
617	  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
618	  // sets. applyCouponToTopup re-validates for this user against the real amount.
619	  const jar = await cookies();
620	  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
621	  let bonusCents = 0;
622	  let couponId: string | null = null;
623	  let couponLabel = "";
624	  if (couponCode) {
625	    const result = await applyCouponToTopup(couponCode, cents);
626	    if (result.ok) {
627	      bonusCents = result.bonusCents;
628	      couponId = result.couponId;
629	      couponLabel = result.label;
630	    } else {
631	      // REFUSE, don't silently drop. The old code fell through and completed the
632	      // top-up with no bonus and no message, so a code that passed validation at
633	      // the preview amount but fails against the real one (a `minAmountCents`
634	      // floor, an exhausted limit, an expiry) simply vanished — the customer paid
635	      // expecting a bonus and got nothing, with nowhere to look. Nothing has been
636	      // charged at this point, so stopping is free and the customer can retry
637	      // without the code or with a larger amount.
638	      return {
639	        error:
640	          `${result.error ?? "That promo code can't be applied to this amount."} ` +
641	          `Nothing has been charged — adjust the amount or remove the code and try again.`,
642	      };
643	    }
644	  }
645	
646	  try {
647	    await db.$transaction(async (tx) => {
648	      // Claim the coupon FIRST, atomically. The old code did an unconditional
649	      // `coupon.update({ timesRedeemed: { increment: 1 } })` after a plain read of
650	      // the cap in the preview, so two top-ups racing for the last slot both saw
651	      // room and both incremented — the limit could be blown past by any number of
652	      // concurrent claims. Mirror `claimOrderCoupon`: a conditional `updateMany`
653	      // gated on `timesRedeemed < max` is the only thing that atomically hands out
654	      // the final slot, and the unique(coupon,user) create fails a double-claim.
655	      if (bonusCents > 0 && couponId) {
656	        const c = await tx.coupon.findUnique({ where: { id: couponId }, select: { maxRedemptions: true } });
657	        const claim = await tx.coupon.updateMany({
658	          where:
659	            c?.maxRedemptions == null
660	              ? { id: couponId, active: true }
661	              : { id: couponId, active: true, timesRedeemed: { lt: c.maxRedemptions } },
662	          data: { timesRedeemed: { increment: 1 } },
663	        });
664	        if (claim.count !== 1) throw new CouponClaimError("That code has just reached its redemption limit.");
665	        try {
666	          await tx.couponRedemption.create({
667	            data: { couponId, userId: user.id, amountCents: bonusCents, context: "topup" },
668	          });
669	        } catch {
670	          throw new CouponClaimError("You’ve already used this code.");
671	        }
672	      }
673	      await tx.user.update({
674	        where: { id: user.id },
675	        data: { balanceCents: { increment: cents + bonusCents } },
676	      });
677	      await tx.walletTransaction.create({
678	        data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
679	      });
680	      if (bonusCents > 0 && couponId) {
681	        await tx.walletTransaction.create({
682	          data: {
683	            userId: user.id,
684	            amountCents: bonusCents,
685	            description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
686	          },
687	        });
688	      }
689	    });
690	  } catch (e) {
691	    // The demo gateway charges nothing external, so a rolled-back transaction
692	    // means the customer is untouched — safe to surface and let them retry.
693	    if (e instanceof CouponClaimError) {
694	      return { error: `${e.message} Nothing has been charged — remove the code and try again.` };
695	    }
696	    throw e;
697	  }
698	  jar.delete(COUPON_COOKIE);
699	  await audit(user.id, "wallet.topup", `$${amount}${bonusCents > 0 ? ` +bonus $${(bonusCents / 100).toFixed(2)}` : ""}`);
700	  // First successful paid action may unlock a referral reward for both parties.
701	  try {
702	    await maybeRewardReferral(user.id);
703	  } catch { /* non-fatal */ }
704	  revalidatePath("/dashboard/billing");
705	  return {};
706	}
