721	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
722	  // Spend path: block wallet debits while an admin is impersonating.
723	  await assertNotImpersonating();
724	  const { user, server } = await ownedServer(serverId);
725	  if (server.isFree || !server.expiresAt) return;
726	  // A MANUAL renewal is a fresh purchase decision, so it is gated. Note this
727	  // cannot strand an existing customer: every account that owns a server today
728	  // predates verification and is grandfathered, and the automatic renewal in
729	  // worker/billing.ts does not pass through here at all — nobody's server lapses
730	  // because of this check.
731	  const unverified = await emailVerificationError(user);
732	  if (unverified) return { error: unverified };
733	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
734	  if (!plan) return;
735	  // A game server carries BOTH a base `planId` and a `gamePlanId`, and it is sold
736	  // at the game plan's FLAT price. Reading only `plan.priceCents` here charged a
737	  // game-server owner the base VPS term price instead — `minecraft-mm8w85` sold at
738	  // $4.99 on a Starter base plan would have been billed $8.99, an 80% overcharge.
739	  const gamePlan = server.gamePlanId
740	    ? await db.gamePlan.findUnique({
741	        where: { id: server.gamePlanId },
742	        select: { name: true, priceCents: true, termMonths: true },
743	      })
744	    : null;
745	  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
746	  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
747	  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
748	    where: { serverId }, select: { id: true },
749	  }));
750	  // Priced through `renewalCharge` — the SAME function the automatic renewal sweep
751	  // in worker/billing.ts and the saved-card path use. Not a second copy of the
752	  // arithmetic: see lib/renewal-quote.ts for both incidents that produced this
753	  // rule, the second of which was a fresh duplicate written hours after the first.
754	  const quote = renewalQuote(
755	    {
756	      termMonths: server.termMonths,
757	      extraDiskGB: server.extraDiskGB,
758	      plan: { name: plan.name, priceCents: plan.priceCents },
759	      gamePlan,
760	      dedicatedIp: hasDedicatedIp ? {} : null,
761	    },
762	    {
763	      ipMonthlyCents: hasDedicatedIp ? await dedicatedIpMonthlyCents() : 0,
764	      extraDiskPerGbCents: await extraDiskPerGbCents(),
765	    },
766	  );
767	  const renewCents = quote.totalCents;
768	  const term = { months: quote.months };
769	  const extraDiskMonthly = await extraDiskMonthlyCents(server.extraDiskGB);
770	  const extraDiskCents = gamePlan ? 0 : extraDiskMonthly * quote.months;
771	  const owner = await db.user.findUnique({ where: { id: server.userId } });
772	  if (!owner || owner.balanceCents < renewCents) {
773	    return { error: "Insufficient balance — top up your wallet first." };
774	  }
775	
776	  // `E` is the expiry we read OUTSIDE the transaction. We advance it with a
777	  // compare-and-swap on that exact value so two concurrent "Renew now" clicks
778	  // can't both read E, both debit, and both write E+term (double-charge, one
779	  // term granted). Only the CAS that matches E wins; the loser is a no-op.
780	  const E = server.expiresAt;
781	  const base = new Date(Math.max(E.getTime(), Date.now()));
782	  const newExpiry = addMonths(base, term.months);
783	
784	  // `renewCents` above is `vpsTermPriceCents(...)` — the REGULAR price, with no
785	  // seasonal promo applied. That is exactly what lib/promotions.ts promises: the
786	  // strikethrough on the marketing page is the real renewal price. So the months
787	  // being added here are sold at 0% off, and the term's stored rate has to say so.
788	  //
789	  // BLENDED, not overwritten. A customer can renew early, stacking a full-price
790	  // term on top of months still running at an intro discount. Overwriting would
791	  // silently reprice those earlier months to full list — and that is the profitable
792	  // direction: buy 36 months at 45% off, renew once at full price, and every one of
793	  // the original discounted months would suddenly credit at the full rate on a
794	  // downgrade. Blending keeps the cash value of the window invariant.
795	  const renewedPercent = prorateBlendPercent({
796	    currentPercent: resolveTermPromoPercent(server.termPromoPercent),
797	    currentMonths: remainingMonths(E, Date.now()),
798	    addedPercent: 0,
799	    addedMonths: term.months,
800	  });
801	  try {
802	    await db.$transaction(async (tx) => {
803	      // Compare-and-swap the expiry first; if it no longer equals E another
804	      // renewal already advanced it — bail without charging (tx rolls back).
805	      const adv = await tx.server.updateMany({
806	        where: { id: serverId, expiresAt: E },
807	        data: {
808	          expiresAt: newExpiry,
809	          termPromoPercent: renewedPercent,
810	          suspendedNote: null,
811	          suspendReason: null,
812	        },
813	      });
814	      if (adv.count === 0) throw new AlreadyRenewedError();
815	      // Atomic guarded debit: a concurrent spend can't drive the wallet negative.
816	      await debitWallet(tx, server.userId, renewCents);
817	      await tx.walletTransaction.create({
818	        data: {
819	          userId: server.userId,
820	          amountCents: -renewCents,
821	          description: `Renewal: ${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
822	        },
823	      });
824	      // PAID invoice inside the same CAS-guarded tx: a losing concurrent "Renew
825	      // now" throws AlreadyRenewedError and rolls back, so no duplicate invoice.
826	      await tx.invoice.create({
827	        data: invoiceCreateData({
828	          userId: server.userId,
829	          description: `Renewal: ${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
830	          status: "PAID",
831	          period: { start: E, end: newExpiry },
832	          lineItems: [
833	            {
834	              description: `${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
835	              qty: 1,
836	              unitCents: renewCents - extraDiskCents,
837	              amountCents: renewCents - extraDiskCents,
838	            },
839	            ...(extraDiskCents > 0
840	              ? [
841	                  {
842	                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthly / 100).toFixed(2)}/mo)`,
843	                    qty: 1,
844	                    unitCents: extraDiskCents,
845	                    amountCents: extraDiskCents,
846	                  },
847	                ]
848	              : []),
849	          ],
850	        }),
851	      });
852	    });
853	  } catch (e) {
854	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
855	    if (e instanceof AlreadyRenewedError) return { error: "This server was just renewed — refresh to see the new expiry." };
856	    throw e;
857	  }
858	  await audit(user.id, "server.renew_now", serverId);
859	
860	  // An UNPAID-suspended server springs back to life once paid — but only that
861	  // kind. This used to fire for ANY suspended server, so a customer suspended for
862	  // outbound abuse could click "Renew now", pay, and put themselves straight back
863	  // on the network, undoing an abuse or admin action with a card. Legacy rows with
864	  // a null `suspendReason` are not auto-lifted; an admin can clear those by hand.
865	  if (server.status === "SUSPENDED" && server.suspendReason === "UNPAID") {
866	    const pending = await db.job.count({
867	      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
868	    });
869	    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
870	  }
871	  revalidatePath(`/dashboard/servers/${serverId}`);
872	}
