876	export async function adminExtendServer(prev: any, formData: FormData): Promise<{ error?: string }> {
877	  const admin = await requireAdmin();
878	  const serverId = String(formData.get("serverId") ?? "");
879	  const days = Number(formData.get("days"));
880	  if (!serverId || !Number.isFinite(days) || days === 0 || Math.abs(days) > 365) {
881	    return { error: "Days must be between -365 and 365." };
882	  }
883	  const server = await db.server.findUnique({ where: { id: serverId } });
884	  if (!server) return { error: "Server not found." };
885	  const base = server.expiresAt ? server.expiresAt.getTime() : Date.now();
886	
887	  // ─── EXPIRESAT INTEGRITY ────────────────────────────────────────────────────
888	  // The whole proration model rests on "every month between now and `expiresAt` is
889	  // a month the customer has actually bought" (see lib/proration.ts
890	  // remainingMonths). This action moves `expiresAt` by up to a year per call, with
891	  // no call limit and no payment — so before the persisted rate existed, an admin
892	  // goodwill gift of 12 months was directly convertible to cash: downgrade the
893	  // gifted server and the prorated credit paid out real wallet money for months
894	  // nobody had ever been charged for. Admin-only, so never a self-service exploit,
895	  // but a support agent clicking "extend" was minting refundable balance.
896	  //
897	  // SEMANTICS CHOSEN: gifted months are recorded as sold at 100% off, and blended
898	  // into the rate the existing months are on. That is the honest reading of a gift
899	  // — those months cost the customer nothing, so nothing may prorate out of them —
900	  // and it is exact rather than blunt: the blend leaves the CASH VALUE of the
901	  // remaining window completely unchanged, so a customer who paid for 12 months and
902	  // was gifted a 13th still gets back precisely what those 12 paid months are worth
903	  // on a downgrade. Zeroing the whole term instead would confiscate what they paid;
904	  // leaving the rate alone is the money printer. Repeated gifts only ever dilute
905	  // toward 100, so no number of calls can raise the payout.
906	  //
907	  // A NEGATIVE `days` removes months rather than adding them, so there is nothing
908	  // to blend in: the customer keeps the rate they bought at over a shorter window,
909	  // which strictly reduces any future credit. Blending negative months would push
910	  // the rate the other way and over-credit what is left.
911	  const gifted = days > 0;
912	  const termPromoPercent = gifted
913	    ? prorateBlendPercent({
914	        currentPercent: resolveTermPromoPercent(server.termPromoPercent),
915	        currentMonths: remainingMonths(server.expiresAt, Date.now()),
916	        addedPercent: 100, // gifted: no cash changed hands for these months
917	        addedMonths: (days * 86400_000) / MS_PER_AVG_MONTH,
918	      })
919	    : resolveTermPromoPercent(server.termPromoPercent);
920	
921	  await db.server.update({
922	    where: { id: serverId },
923	    data: { expiresAt: new Date(base + days * 86400_000), termPromoPercent },
924	  });
925	  await audit(
926	    admin.id,
927	    "admin.extend_server",
928	    `${serverId} ${days}d${gifted ? ` gifted (rate basis ${server.termPromoPercent ?? "null"}% -> ${termPromoPercent}% off)` : ""}`,
929	  );
930	  revalidatePath("/admin/subscriptions");
931	  return {};
932	}
