10	const GOOGLE_ERRORS: Record<string, string> = {
11	  google_unavailable: "Google sign-in isn't set up on this server yet. Use your email and password.",
12	  google_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
13	  google_cancelled: "Google sign-in was cancelled.",
14	  google_state: "That Google sign-in link expired or didn't match. Please try again.",
15	  google_unverified: "Your Google email isn't verified, so we can't sign you in with it.",
16	  google_error: "Couldn't finish signing in with Google. Please try again.",
17	  account_suspended: "This account is suspended.",
18	};
