20	export default async function RegisterPage({
21	  searchParams,
22	}: {
23	  searchParams: Promise<{ next?: string; error?: string }>;
24	}) {
25	  // Where the visitor was heading before hitting the sign-up wall. Carried
26	  // through the Google OAuth flow so first sign-in lands them where they meant to
27	  // go. Validated by `safeNext` — an unchecked `next` is an open redirect and
28	  // therefore a phishing primitive — so it is never trusted, here or in the action.
29	  const { next, error } = await searchParams;
30	  const dest = safeNext(next ?? null);
31	  // Only ever surface a message from our own fixed map — never echo the raw
32	  // query value into the page.
33	  const googleError = error ? GOOGLE_ERRORS[error] : undefined;
34	
35	  // Already signed in? Then this page is a waypoint: send them onward instead of
36	  // asking a paying customer to authenticate again.
37	  const user = await currentUser();
38	  if (user) redirect(dest ?? (user.role === "ADMIN" ? "/admin" : "/dashboard"));
39	
40	  return (
41	    <AuthShell
42	      heading="Create your account"
43	      sub="Deploy your first server in under a minute."
44	      // Two of these three were untrue. "No credit card required to get started"
45	      // implied a free first server — free deploys are admin-only, and a customer
46	      // with a $0 wallet gets "Insufficient balance. Top up your wallet first."
47	      // And "18+ OS images" was a hardcode the live catalogue passed long ago:
48	      // the homepage counts the same catalogue and renders 31+. A number nothing
49	      // computes goes stale by default, so this states the capability instead.
50	      bullets={[
51	        "Free to create — you pay when you deploy",
52	        "One-click OS images, control panels and apps",
53	        "Pay monthly, cancel anytime",
54	      ]}
55	    >
56	      <ReferralCapture />
