"use client";

import { useEffect } from "react";

/**
 * Fire a conversion on a server-RENDERED success page, where the success signal
 * is the render/redirect itself and there is no client submit handler to hook.
 *
 * The matching server-side Meta CAPI event has already fired (with this same
 * `eventId`), so the browser pixel this triggers dedupes to ONE conversion. Best
 * effort throughout: `window.nxTrack` is installed by ConversionTags only when an
 * ad ID is configured, so the guard makes this a no-op otherwise, and any failure
 * is swallowed — a tracking hiccup must never surface to the customer.
 */
export function FireConversion({
  event,
  value,
  currency = "USD",
  eventId,
}: {
  event: "Purchase" | "Lead";
  value?: number;
  currency?: string;
  eventId?: string;
}) {
  useEffect(() => {
    try {
      const track = (window as unknown as { nxTrack?: (e: string, p?: unknown) => void }).nxTrack;
      if (typeof track === "function") track(event, { value, currency, eventId });
    } catch {
      /* tracking is best-effort — never break the page over it */
    }
    // Fire exactly once, on mount: the page only renders with these props right
    // after the conversion happened.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return null;
}

